using System;
using UnityEngine;
public static class PrototypeScenarioTests {
 static void Check(bool value,string message){if(!value)throw new Exception("SCENARIO: "+message);}
 static MapData LoadMap(){if(ProjectMapBuild.HasSource)return ProjectMapStore.Load(ProjectMapBuild.Root).Compose();var legacy=Resources.Load<TextAsset>("eungye-hybrid-map");if(!legacy)throw new Exception("SCENARIO: neither project map nor legacy fixture is available");return JsonUtility.FromJson<MapData>(legacy.text);}
 public static void Coverage(){var map=LoadMap();var hd=new HdRoadGraph(map);foreach(int c in new[]{1182,1158,1180,1050,1248,1133,1351,1368,1392}){int count=0;string pairs="";for(int a=0;a<map.stops.Length;a++)for(int b=0;b<map.stops.Length;b++){if(a==b)continue;var x=map.stops[a];var y=map.stops[b];var r=hd.Route(x.laneEdge,x.laneAt,y.laneEdge,y.laneAt);if(PrototypeScenario.Valid(r,c)){count++;pairs+=" "+a+">"+b+":"+r.path.length.ToString("F0");}}Debug.Log("NATURAL_COVERAGE "+c+" count="+count+pairs);}}
 public static void Run(){var map=LoadMap();var hd=new HdRoadGraph(map);var courses=PrototypeScenario.Build(hd,map.stops);foreach(var s in courses)Debug.Log("SCENARIO_ROUTE "+s.id+" pickup="+(s.pickup+1)+" drop="+(s.drop+1)+" connector="+s.connector+" length="+s.route.path.length+" alternate="+s.alternate);
  Check(courses.Count==9,"all nine valid directed normal-map courses; actual="+courses.Count);
  foreach(var id in new[]{"PS05","PS06","PS07"}){var course=courses.Find(s=>s.id==id);Check(course!=null&&course.variant==0,id+" retains its transport route without fictional permissive-left operation");}
  Check(!ConfusionPractice.AllowsServiceVariant(12)&&!ConfusionPractice.AllowsServiceVariant(13)&&!ConfusionPractice.AllowsServiceVariant(14),"fictional left conditions are standalone practice only");
  foreach(var variant in new[]{8,9,10,11})Check(ConfusionPractice.AllowsServiceVariant(variant),"other service conditions retained "+variant);
  foreach(var variant in new[]{12,13,14})Check(ServiceLawZones.IsRetiredZoneId("eungye-law-"+variant+"-1248"),"legacy left observation migration "+variant);
  foreach(var id in new[]{"eungye-law-11-1248","eungye-law-13--1","eungye-law-13-unknown","unrelated"})Check(!ServiceLawZones.IsRetiredZoneId(id),"unknown saved IDs cannot silently migrate "+id);
  var fixture=new GameObject("retired service condition gate");try{var live=fixture.AddComponent<ConfusionPractice>();var j=new TrafficJunction{leftTurnMode=LeftTurnMode.ProtectedShared};foreach(var variant in new[]{12,13,14}){var zone=new ServiceLawZone{variant=variant,junction=j};Check(!live.CanStartInService(zone)&&!live.StartInService(zone)&&!live.Active&&j.leftTurnMode==LeftTurnMode.ProtectedShared,"retired service condition cannot touch signal "+variant);}}finally{UnityEngine.Object.DestroyImmediate(fixture);}
  fixture=new GameObject("retired service save migration");try{var zones=fixture.AddComponent<ServiceLawZones>();typeof(ServiceLawZones).GetProperty("Ready").SetValue(zones,true,null);zones.scenarios.AddRange(courses);foreach(var id in new[]{"PS05","PS06","PS07"}){int variant=id=="PS05"?12:id=="PS06"?13:14;zones.RestoreLive(new ServiceLawZonesSnapshot{scenarioId=id,assignedId="eungye-law-"+variant+"-1248",sequence=6,hasObservation=true,observation=new ConfusionLiveSnapshot{state=new ConfusionPracticeState(variant).Snapshot()}});Check(zones.CurrentScenario.id==id&&zones.Assigned==null&&zones.CaptureLive().observation==null,id+" saved transport retained while obsolete active override discarded");Check(zones.ZoneFor(new JobOffer{scenarioId=id,zoneIndex=0})==null,id+" stale offer index cannot reassign a new condition");}foreach(int variant in new[]{12,13,14}){zones.RestoreLive(new ServiceLawZonesSnapshot{lastTitle=ConfusionPracticeState.Title(variant),hasFeedback=true,lastFeedback=new PracticeFeedback{outcome="old permissive result"}});Check(zones.LastFeedback==null&&string.IsNullOrEmpty(zones.LastTitle),"ended legacy trip cannot retain retired permissive TIP "+variant);}bool rejected=false;try{zones.RestoreLive(new ServiceLawZonesSnapshot{scenarioId="PS05",assignedId="unknown-zone"});}catch(ArgumentException){rejected=true;}Check(rejected,"unrelated removed saved zone still rejects corrupt save");}finally{UnityEngine.Object.DestroyImmediate(fixture);}
  foreach(var s in courses){var a=map.stops[s.pickup];var b=map.stops[s.drop];var natural=hd.Route(a.laneEdge,a.laneAt,b.laneEdge,b.laneAt);Check(natural!=null&&string.Join(",",natural.edges)==string.Join(",",s.route.edges),s.id+" ordinary stop-to-stop route without forced waypoint");Check(PrototypeScenario.Valid(s.route,s.connector),s.id+" approach/exit distance and no repeated mandatory connector");foreach(int e in s.route.edges)Check(!hd.edges[e].disabled,s.id+" never disabled");Check(s.route.edges[s.route.edges.Count-1]==map.stops[s.beforePickup?s.pickup:s.drop].laneEdge,s.id+" actual curb destination lane");if(s.id=="PS08")Check(s.alternative!=null&&!s.alternative.edges.Contains(s.connector)&&s.alternate>=0&&s.alternate!=s.alternative.edges[0]&&hd.edges[s.alternate].id.StartsWith("join:"),"PS08 distinct interior directed bypass");if(s.id=="PS09")Check(hd.edges[s.connector].turn==1,"PS09 actual right turn");}
  var exit=courses.Find(s=>s.id=="PS08");foreach(var point in new[]{exit.route.path.Position(0),map.stops[exit.pickup].Kerb}){float at;int start=hd.Nearest(point+Vector3.up*.65f,exit.route.path.Tangent(0),out at);var to=map.stops[exit.drop];var detour=hd.Route(start,at,to.laneEdge,to.laneAt,PrototypeScenario.AvoidWeights(hd,exit.connector));Debug.Log("SCENARIO_DETOUR start="+start+" at="+at+" via="+exit.alternate+" goal="+to.laneEdge+" at="+to.laneAt+" route="+(detour==null?"null":string.Join(",",detour.edges)));Check(detour!=null&&!detour.edges.Contains(exit.connector),"runtime nearest pickup/kerb detour is valid");}
  Debug.Log("PROTOTYPE_SCENARIO_TESTS_OK");
 }
}
